function bestHaulRing(nums: number[]): number {
  const n = nums.length;
  if (n === 1) return nums[0];
  const go = (i: number, tookFirst: boolean): number => {
    if (i >= n) return 0;
    const skip = go(i + 1, tookFirst);
    if (i === n - 1 && tookFirst) return skip; // last touches first
    return Math.max(skip, nums[i] + go(i + 2, tookFirst || i === 0));
  };
  return go(0, false);
}

