    def bestHaulRing(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]

        def go(i: int, took_first: bool) -> int:
            if i >= n:
                return 0
            skip = go(i + 1, took_first)
            if i == n - 1 and took_first:  # last touches first
                return skip
            return max(skip, nums[i] + go(i + 2, took_first or i == 0))

        return go(0, False)

