function bestHaulRing(nums: number[]): number {
  const n = nums.length;
  if (n === 1) return nums[0];
  const line = (lo: number, hi: number): number => {
    let prev2 = 0, prev1 = 0;
    for (let i = lo; i <= hi; i++) [prev2, prev1] = [prev1, Math.max(prev1, prev2 + nums[i])];
    return prev1;
  };
  return Math.max(line(0, n - 2), line(1, n - 1));
}

